-- Ekran — içerik aktarımı (npm run aktar -- --sql ile üretildi)
-- Supabase panelinde SQL Editor'a yapıştırıp çalıştırın.
-- Tekrar çalıştırmak güvenlidir: her kayıt upsert edilir, silme yapılmaz.

begin;

-- diziler: 1 kayıt
on conflict (kod) do update set
  veri = excluded.veri;

-- bolumler: 1 kayıt
on conflict (dizi, no) do update set
  veri = excluded.veri;

-- karakterler: 2 kayıt
on conflict (id) do update set
  dizi = excluded.dizi,
  veri = excluded.veri;

-- cihazlar: 3 kayıt
on conflict (kod) do update set
  karakter = excluded.karakter,
  veri = excluded.veri;

-- hesaplar: 5 kayıt
on conflict (id) do update set
  dizi = excluded.dizi,
  modul = excluded.modul,
  veri = excluded.veri;

-- icerikler: 13 kayıt
on conflict (id) do update set
  dizi = excluded.dizi,
  tur = excluded.tur,
  veri = excluded.veri;

-- sahneler: 8 kayıt
on conflict (kod) do update set
  dizi = excluded.dizi,
  bolum = excluded.bolum,
  veri = excluded.veri;

commit;
